export function AccessibilityDemo({
  altOn = {{altOn}},
  contrastOn = {{contrastOn}},
  labelOn = {{labelOn}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: 340, display: "flex", flexDirection: "column", gap: 10, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <span role="img" aria-label={altOn ? "Mountain sunset" : undefined}
          style={{ width: 40, height: 40, borderRadius: 8, background: accent, display: "grid", placeItems: "center", fontWeight: 700 }}>{altOn ? "\u25A1" : "?"}</span>
        <p style={{ margin: 0, fontSize: 12, fontFamily: "ui-monospace, monospace", color: "#241430aa" }}>{altOn ? 'alt="Mountain sunset"' : "alt missing"}</p>
      </div>
      <p style={contrastOn ? {} : { color: "#FAF7F2", background: "#FAF7F2", textShadow: "0 0 0 #d8d2c8" }}>Body copy people can actually read</p>
      <button type="button" aria-label={labelOn ? "Close" : undefined}
        style={{ width: 32, height: 32, border: "none", borderRadius: 8, background: accent, cursor: "pointer", fontSize: 16 }}>&times;</button>
      <p style={{ margin: 0, fontSize: 12, fontFamily: "ui-monospace, monospace", color: "#241430aa" }}>{labelOn ? 'button has aria-label="Close"' : "button has no accessible name"}</p>
    </div>
  );
}
